INSERT INTO perguntas (texto, tema, resposta_correta, explicacao, ativa, nivel) VALUES
('Usar a mesma senha em varios sites e uma pratica segura, desde que a senha seja complexa.', 'Senhas', 0, 'Reutilizar senhas e arriscado: se um dos servicos for invadido, todos os outros que usam a mesma senha ficam vulneraveis, independente da complexidade.', 1, 1),
('Bancos costumam enviar SMS pedindo para o cliente confirmar a senha para evitar o bloqueio da conta.', 'Phishing', 0, 'Instituicoes financeiras legitimas nunca pedem senha por SMS. Essa e uma tecnica classica de phishing/smishing.', 1, 1),
('A autenticacao de dois fatores (2FA) torna a conta mais segura porque exige mais do que apenas a senha.', 'Autenticação Multifator', 1, 'O 2FA combina a senha (algo que voce sabe) com um segundo elemento, como um codigo no celular, dificultando o acesso mesmo que a senha seja descoberta.', 1, 1),
('Navegar em uma aba anonima do navegador torna qualquer site totalmente seguro contra invasoes.', 'Navegação Segura', 0, 'A aba anonima apenas evita salvar historico e cookies localmente; ela nao protege contra sites maliciosos, malware ou vazamento de dados.', 1, 1),
('Manter os aplicativos e o sistema do celular atualizados ajuda a corrigir falhas de seguranca conhecidas.', 'Atualizações', 1, 'Atualizacoes frequentemente trazem correcoes para vulnerabilidades ja descobertas, reduzindo a chance de um ataque explorar essas falhas.', 1, 1),
('Receber uma ligacao de alguem dizendo ser do ''suporte tecnico'' e pedindo acesso remoto ao computador e algo comum e seguro.', 'Engenharia Social', 0, 'Esse e um golpe clssico de engenharia social. Suporte tecnico legitimo raramente liga sem voce ter aberto um chamado antes.', 1, 1),
('Um anexo de e-mail pode conter virus mesmo que o remetente pareca ser um contato conhecido.', 'Malware', 1, 'Contas legitimas podem ser invadidas e usadas para espalhar malware, por isso anexos inesperados merecem desconfianca mesmo vindo de contatos conhecidos.', 1, 1),
('Publicar sua localizacao em tempo real nas redes sociais para todo mundo ver nao traz nenhum risco.', 'Redes Sociais', 0, 'Compartilhar localizacao em tempo real publicamente pode revelar quando sua casa esta vazia ou sua rotina diaria, o que e um risco de seguranca.', 1, 1),
('Verificar o endereco do remetente antes de clicar em um link do e-mail ajuda a identificar phishing.', 'Segurança de E-mail', 1, 'Emails de phishing costumam usar enderecos parecidos com os originais, mas com pequenas diferencas que a verificacao cuidadosa pode revelar.', 1, 1),
('Redes Wi-Fi publicas e abertas (sem senha) sao tao seguras quanto a rede da sua casa.', 'Segurança em Redes Wi-Fi', 0, 'Redes abertas facilitam que outras pessoas na mesma rede intercepetem os dados trafegados, por isso exigem mais cuidado.', 1, 1),
('Fazer backups regulares dos seus arquivos ajuda a recuperar dados caso o computador seja infectado por ransomware.', 'Backups', 1, 'Com uma copia de seguranca atualizada e guardada separadamente, e possivel restaurar os arquivos sem precisar pagar resgate a um criminoso.', 1, 1),
('Usar a senha do seu e-mail principal em sites de compras online e uma boa forma de nao esquecer a senha.', 'Senhas', 0, 'O e-mail costuma ser usado para recuperar o acesso a outras contas, entao reutilizar a senha dele em outros lugares e especialmente arriscado.', 1, 1),
('Mensagens que dizem ''sua conta sera bloqueada em 1 hora, clique aqui agora'' costumam ser um sinal de phishing.', 'Phishing', 1, 'Criar urgencia e uma tatica comum usada por criminosos para impedir que a vitima pense com calma antes de agir.', 1, 1),
('Baixar aplicativos apenas de lojas oficiais (como Google Play e App Store) reduz o risco de instalar malware.', 'Downloads', 1, 'As lojas oficiais tem processos de verificacao que dificultam, embora nao eliminem totalmente, a distribuicao de apps maliciosos.', 1, 1),
('Perguntas de seguranca com respostas faceis de achar em redes sociais, como ''nome do seu primeiro animal'', sao totalmente seguras.', 'Autenticação', 0, 'Informacoes publicadas em redes sociais podem ser usadas por criminosos para responder perguntas de seguranca e invadir contas.', 1, 1),
('O cadeado (HTTPS) que aparece no navegador garante que o site e sempre confiavel e nunca e falso.', 'Navegação Segura', 0, 'O HTTPS garante apenas que a conexao e criptografada, e nao que o conteudo do site seja legitimo. Sites falsos tambem podem usar HTTPS.', 1, 1),
('Compartilhar sua senha com um colega de confianca para resolver um problema pontual e uma pratica segura.', 'Senhas', 0, 'Senhas sao pessoais e intransferiveis. Compartilhar, mesmo com alguem de confianca, aumenta o risco de vazamento e dificulta saber quem fez o que.', 1, 1),
('Golpes de engenharia social podem acontecer por telefone, e-mail, mensagem de texto ou pessoalmente.', 'Engenharia Social', 1, 'A engenharia social explora a confianca humana e pode ocorrer por qualquer canal de comunicacao, nao apenas pela internet.', 1, 1),
('Um virus de computador so pode infectar a maquina se o usuario baixar um arquivo de um site desconhecido.', 'Vírus', 0, 'Virus tambem podem chegar por pendrives infectados, anexos de e-mail, links maliciosos e falhas de seguranca nao corrigidas.', 1, 1),
('Clicar em um link recebido de um numero desconhecido no WhatsApp, sem verificar antes, e uma atitude segura.', 'Links Maliciosos', 0, 'Links de numeros desconhecidos podem levar a sites falsos de phishing ou instalar malware no aparelho; o ideal e verificar antes de clicar.', 1, 1),
('Ransomware e um tipo de malware que bloqueia ou criptografa arquivos e exige pagamento para liberar o acesso.', 'Ransomware', 1, 'O ransomware sequestra os dados da vitima e cobra um resgate, geralmente em criptomoeda, para supostamente devolver o acesso.', 1, 1),
('Desligar o Wi-Fi e o Bluetooth do celular quando nao estao em uso pode reduzir riscos de seguranca.', 'Segurança em Dispositivos Móveis', 1, 'Conexoes sem fio ativas e desnecessarias aumentam a superficie de ataque do dispositivo, permitindo tentativas de conexao indevida.', 1, 1),
('Se um site pede seu CPF e data de nascimento so para ''liberar um premio'', e seguro informar sem verificar a origem.', 'Dados Pessoais', 0, 'Pedidos de dados pessoais associados a premios inesperados sao um golpe comum para roubo de identidade.', 1, 1),
('Um vazamento de dados acontece quando informacoes privadas sao expostas ou acessadas sem autorizacao.', 'Vazamento de Dados', 1, 'Vazamentos podem ocorrer por falhas de seguranca, ataques ou erros humanos, expondo dados pessoais ou corporativos.', 1, 1),
('Ignorar atualizacoes do sistema operacional por meses nao traz nenhum risco extra de seguranca.', 'Atualizações', 0, 'Atualizacoes atrasadas deixam o dispositivo exposto a vulnerabilidades ja conhecidas e corrigidas nas versoes mais recentes.', 1, 1),
('Receber uma mensagem informando que voce ganhou um premio em um sorteio do qual nunca participou e um sinal de alerta.', 'Golpes Digitais', 1, 'Premios de sorteios que a pessoa nunca participou sao uma isca comum usada em golpes para roubar dados ou dinheiro.', 1, 1),
('E seguro fornecer o codigo de verificacao (SMS) recebido no celular para alguem que diz ser do banco por telefone.', 'Autenticação Multifator', 0, 'O codigo de verificacao deve ser usado apenas por voce, na propria tela de login; nenhuma instituicao legitima pede esse codigo por telefone.', 1, 1),
('Usar senhas curtas e faceis de lembrar, como ''123456'', e uma boa pratica de seguranca.', 'Senhas', 0, 'Senhas simples e previsiveis sao facilmente descobertas por ataques automatizados de tentativa e erro.', 1, 1),
('Postar fotos de documentos como RG ou CPF em grupos publicos de redes sociais e uma pratica segura.', 'Redes Sociais', 0, 'Documentos pessoais expostos publicamente podem ser usados para fraudes e roubo de identidade.', 1, 1),
('Um antivirus atualizado ajuda a detectar e bloquear varios tipos de malware conhecidos.', 'Malware', 1, 'Antivirus atualizados possuem bases de dados recentes de ameacas conhecidas, o que aumenta a chance de deteccao.', 1, 1),
('Antes de instalar um aplicativo, verificar as avaliacoes e as permissoes solicitadas e uma boa pratica.', 'Segurança em Dispositivos Móveis', 1, 'Permissoes exageradas (como um app de lanterna pedindo acesso a contatos) e avaliacoes ruins podem indicar riscos.', 1, 1),
('Sites de phishing sempre tem erros de portugues visiveis, entao um texto bem escrito garante que o site e legitimo.', 'Phishing', 0, 'Paginas de phishing modernas podem ser bem escritas e visualmente idnticas as originais; a ausencia de erros nao garante seguranca.', 1, 1),
('Backups devem ser guardados apenas no mesmo computador onde estao os arquivos originais.', 'Backups', 0, 'Guardar o backup so no mesmo local dos dados originais faz com que ele tambem seja perdido em caso de roubo, incendio ou ataque de ransomware.', 1, 1),
('Golpistas podem se passar por parentes em apuros pelo WhatsApp para pedir transferencias de dinheiro com urgencia.', 'Golpes Digitais', 1, 'O golpe do ''parente em apuros'' costuma usar fotos de perfil clonadas e urgencia emocional para convencer a vitima a transferir dinheiro rapidamente.', 1, 1),
('Trocar a senha padrao do roteador Wi-Fi de casa e uma medida recomendada de seguranca.', 'Segurança em Redes Wi-Fi', 1, 'Senhas padrao de fabrica sao conhecidas publicamente e facilmente exploradas por invasores para acessar a rede domestica.', 1, 1),
('Ao vender ou descartar um celular antigo, nao e necessario apagar os dados pessoais antes.', 'Segurança em Dispositivos Móveis', 0, 'Sem apagar os dados (restauracao de fabrica), quem receber o aparelho pode acessar fotos, contas e informacoes pessoais salvas nele.', 1, 1),
('Golpes por e-mail costumam se aproveitar de datas como Black Friday e Natal para enviar falsas promocoes.', 'Phishing', 1, 'Datas de grande volume de compras online sao aproveitadas por criminosos para disfarcar phishing como ofertas imperdiveis.', 1, 1),
('Todo arquivo com extensao .pdf e sempre seguro, pois PDFs nunca podem conter conteudo malicioso.', 'Malware', 0, 'PDFs podem conter links maliciosos, scripts ou explorar vulnerabilidades do leitor de PDF para instalar malware.', 1, 1),
('Ativar a verificacao em duas etapas no e-mail e uma forma simples de aumentar a seguranca da conta.', 'Autenticação Multifator', 1, 'Essa funcionalidade, disponivel na maioria dos provedores de e-mail, adiciona uma camada extra de protecao alem da senha.', 1, 1),
('E seguro usar o mesmo PIN do cartao bancario como senha de outros aplicativos.', 'Senhas', 0, 'Reutilizar o PIN bancario em outros lugares aumenta o risco de que, se vazado, seja usado para acessar a conta bancaria.', 1, 1),
('Mensagens de texto (SMS) tambem podem ser usadas por criminosos para aplicar golpes de phishing, chamados de smishing.', 'Phishing', 1, 'O smishing e uma variacao do phishing feita por SMS, geralmente com links falsos disfarcados de entregas, bancos ou promocoes.', 1, 1),
('Clicar em anuncios muito vantajosos como ''90% de desconto'' em sites desconhecidos e sempre seguro.', 'Links Maliciosos', 0, 'Ofertas exageradamente vantajosas em sites desconhecidos sao uma isca comum para levar a paginas falsas ou instalar malware.', 1, 1),
('Manter o antivirus do computador desativado para o computador ''ficar mais rapido'' e uma boa ideia.', 'Malware', 0, 'Desativar o antivirus remove uma camada importante de protecao, deixando o computador mais vulneravel a infeccoes.', 1, 1),
('Uma senha forte deve combinar letras maiusculas, minusculas, numeros e simbolos.', 'Senhas', 1, 'Combinar diferentes tipos de caracteres aumenta a quantidade de combinacoes possiveis, tornando a senha mais dificil de ser descoberta.', 1, 1),
('E seguro conectar um pendrive desconhecido, encontrado na rua, diretamente no computador do trabalho sem verificar.', 'Malware', 0, 'Pendrives desconhecidos podem estar infectados com malware programado para rodar automaticamente ao serem conectados.', 1, 1),
('Golpistas costumam criar perfis falsos em redes sociais se passando por lojas ou empresas conhecidas.', 'Redes Sociais', 1, 'Perfis falsos imitando marcas conhecidas sao usados para anunciar produtos que nunca serao entregues ou para roubar dados de pagamento.', 1, 1),
('Ler a politica de privacidade de um aplicativo antes de aceitar ajuda a entender que dados serao coletados.', 'Privacidade', 1, 'A politica de privacidade informa quais dados o aplicativo coleta e como serao usados, ajudando o usuario a decidir se aceita ou nao.', 1, 1),
('Instalar qualquer extensao de navegador, mesmo de fontes desconhecidas, nao traz riscos de seguranca.', 'Navegação Segura', 0, 'Extensoes maliciosas podem roubar dados de navegacao, senhas digitadas e ate injetar anuncios ou malware nas paginas visitadas.', 1, 1),
('Um incidente de seguranca e qualquer evento que comprometa a confidencialidade, integridade ou disponibilidade de dados.', 'Incidentes de Segurança', 1, 'Essa e a definicao geral usada na area de seguranca da informacao para caracterizar um incidente.', 1, 1),
('Compartilhar a senha do Wi-Fi de casa com visitas ocasionais, usando uma rede de convidados separada, e uma boa pratica.', 'Segurança em Redes Wi-Fi', 1, 'Uma rede de convidados isola os dispositivos visitantes da rede principal, protegendo computadores e arquivos pessoais.', 1, 1),
('Se um e-mail suspeito parece vir do seu chefe pedindo uma transferencia urgente, deve-se confirmar por outro canal antes de agir.', 'Engenharia Social', 1, 'Esse e o golpe conhecido como ''fraude do CEO''; confirmar por telefone ou pessoalmente evita cair em pedidos falsos com urgencia forcada.', 1, 1),
('Boas praticas de seguranca da informacao incluem nunca deixar o computador desbloqueado ao se ausentar do posto de trabalho.', 'Boas Práticas de Segurança da Informação', 1, 'Bloquear a tela ao se ausentar impede que outras pessoas acessem informacoes ou sistemas sem autorizacao.', 1, 1),
('Aplicativos de mensagens com criptografia de ponta a ponta, como recursos de seguranca, protegem o conteudo das conversas contra interceptacao.', 'Privacidade', 1, 'A criptografia de ponta a ponta garante que apenas remetente e destinatario consigam ler o conteudo das mensagens.', 1, 1),
('Um vazamento de dados de uma empresa nunca afeta os clientes, apenas a propria empresa.', 'Vazamento de Dados', 0, 'Quando dados de clientes (como CPF, e-mail e senha) sao vazados, os proprios clientes podem sofrer fraudes e golpes.', 1, 1),
('Verificar se um site de compras tem informacoes de contato, CNPJ e politica de troca claras ajuda a identificar lojas confiaveis.', 'Golpes Digitais', 1, 'Lojas falsas costumam esconder ou nao ter informacoes claras de contato e CNPJ, o que e um sinal de alerta.', 1, 1),
('Todo pop-up que aparece dizendo ''seu computador esta infectado, clique aqui para limpar'' e sempre um alerta legitimo do sistema.', 'Malware', 0, 'Esses pop-ups sao geralmente golpes chamados de ''scareware'', que tentam assustar o usuario para que instale falsos antivirus maliciosos.', 1, 1),
('Manter um caderno de senhas anotado a mao, guardado em local seguro, e mais seguro do que usar a mesma senha em tudo.', 'Senhas', 1, 'Embora um gerenciador de senhas seja mais pratico, anotar senhas unicas e distintas em um local fisico seguro ainda e melhor do que reutilizar a mesma senha em todos os servicos.', 1, 1),
('Aceitar automaticamente todas as permissoes de um aplicativo, sem revisar quais sao, e uma pratica recomendada.', 'Segurança em Dispositivos Móveis', 0, 'Revisar as permissoes evita conceder acesso desnecessario a cameras, microfone, contatos ou localizacao.', 1, 1),
('Redes sociais podem revelar, mesmo sem querer, informacoes como rotina diaria, familia e localizacao a partir de fotos e postagens.', 'Privacidade', 1, 'Detalhes aparentemente inofensivos em fotos e postagens podem, somados, revelar padroes de rotina e informacoes pessoais sensiveis.', 1, 1),
('Empresas devem ter politicas claras de seguranca da informacao para orientar como os funcionarios lidam com dados sensiveis.', 'Segurança Corporativa', 1, 'Politicas de seguranca corporativa ajudam a padronizar boas praticas e reduzir riscos causados por erro humano.', 1, 1),
('Se voce perceber uma cobranca desconhecida no cartao, o ideal e contatar o banco imediatamente para verificar e, se necessario, bloquear o cartao.', 'Boas Práticas de Segurança da Informação', 1, 'Agir rapido ao notar uma cobranca suspeita ajuda a limitar o prejuizo e permite que o banco investigue ou reverta a transacao.', 1, 1),
('Um gerenciador de senhas ajuda a criar e armazenar senhas unicas e complexas para cada servico.', 'Senhas', 1, 'Gerenciadores de senha geram combinacoes fortes e guardam tudo criptografado, eliminando a necessidade de memorizar ou reutilizar senhas.', 1, 2),
('E seguro acessar o internet banking usando o Wi-Fi aberto de um shopping ou aeroporto, sem nenhuma precaucao extra.', 'Segurança em Redes Wi-Fi', 0, 'Redes publicas abertas facilitam a interceptacao de dados; o ideal e usar dados moveis ou uma VPN confiavel para acessar servicos sensiveis.', 1, 2),
('Ao receber um boleto por e-mail, e recomendado conferir o codigo de barras e os dados do beneficiario antes de pagar.', 'Golpes Digitais', 1, 'Golpistas alteram boletos trocando o beneficiario e o codigo de barras para redirecionar o pagamento para a propria conta.', 1, 2),
('A dupla verificacao (2FA) via aplicativo autenticador e geralmente mais segura do que receber o codigo por SMS.', 'Autenticação Multifator', 1, 'SMS pode ser interceptado por tecnicas como troca de chip (SIM swap), enquanto apps autenticadores geram codigos localmente no aparelho.', 1, 2),
('Clicar em ''cancelar assinatura'' em um e-mail de spam nao solicitado e sempre uma atitude segura.', 'Segurança de E-mail', 0, 'Em e-mails de spam ou phishing, o link de ''cancelar assinatura'' pode confirmar que o endereco esta ativo ou levar a um site malicioso.', 1, 2),
('Golpes de falso suporte tecnico costumam instruir a vitima a instalar programas de acesso remoto, como AnyDesk ou TeamViewer.', 'Engenharia Social', 1, 'Apos convencer a vitima de que ha um problema no computador, o golpista pede a instalacao desses programas para assumir o controle e roubar dados ou dinheiro.', 1, 2),
('Um QR Code encontrado colado sobre outro em um parquimetro ou cardapio pode redirecionar para um site falso.', 'Links Maliciosos', 1, 'Essa tecnica, chamada de ''quishing'', usa QR Codes falsos coladas sobre os originais para levar a paginas de phishing.', 1, 2),
('Atualizar aplicativos automaticamente, quando possivel, ajuda a manter as correcoes de seguranca sempre em dia.', 'Atualizações', 1, 'Atualizacoes automaticas reduzem a janela de tempo em que o dispositivo fica exposto a vulnerabilidades ja corrigidas pelo desenvolvedor.', 1, 2),
('E seguro reutilizar a senha do trabalho em contas pessoais, desde que a senha seja forte.', 'Senhas', 0, 'Se a conta pessoal for comprometida, a senha reutilizada pode dar acesso a sistemas corporativos, ampliando o impacto do incidente.', 1, 2),
('Backups seguindo a regra 3-2-1 (3 copias, 2 midias diferentes, 1 fora do local) sao considerados uma boa pratica.', 'Backups', 1, 'Essa regra reduz a chance de perder todos os dados simultaneamente por falha de hardware, roubo, incendio ou ransomware.', 1, 2),
('Perfis falsos em redes sociais que imitam perfis de bancos costumam responder rapidamente a reclamacoes publicas para roubar dados.', 'Redes Sociais', 1, 'Golpistas monitoram reclamacoes publicas de clientes e respondem se passando pelo banco, direcionando a vitima para um chat privado onde pedem dados sensiveis.', 1, 2),
('Verificar se o remetente de um e-mail corporativo usa o dominio oficial da empresa ajuda a identificar tentativas de phishing direcionado.', 'Segurança de E-mail', 1, 'Ataques de spear phishing costumam usar dominios muito parecidos com o oficial, com pequenas alteracoes dificeis de notar.', 1, 2),
('Ao configurar um novo roteador, manter o firmware desatualizado por anos nao representa risco algum.', 'Segurança em Redes Wi-Fi', 0, 'Firmwares desatualizados podem conter vulnerabilidades conhecidas que permitem a um atacante controlar o roteador ou espionar a rede.', 1, 2),
('Aplicativos de compartilhamento de tela devem ser usados com cautela, pois podem expor senhas e dados sensiveis na tela durante uma chamada.', 'Boas Práticas de Segurança da Informação', 1, 'Notificacoes, senhas salvas e conversas privadas podem aparecer acidentalmente na tela durante o compartilhamento se nao houver cuidado previo.', 1, 2),
('Ransomware so afeta grandes empresas, nunca pessoas fisicas usando computadores domesticos.', 'Ransomware', 0, 'Ransomware pode infectar qualquer dispositivo vulneravel, incluindo computadores pessoais, criptografando fotos e arquivos particulares.', 1, 2),
('Verificar a URL completa de um site bancario, e nao apenas o nome que aparece na aba do navegador, ajuda a evitar sites falsos.', 'Navegação Segura', 1, 'Paginas falsas podem usar titulos de aba identicos aos originais; a URL real na barra de endereco e o indicador mais confiavel.', 1, 2),
('Compartilhar capturas de tela de conversas privadas de terceiros sem autorizacao nao levanta nenhuma questao de privacidade.', 'Privacidade', 0, 'Compartilhar conversas privadas de outras pessoas sem consentimento pode violar a privacidade delas e, dependendo do conteudo, ter implicacoes legais.', 1, 2),
('Golpes de ''falso emprego'', que pedem pagamento antecipado por materiais ou treinamento, sao um sinal comum de fraude.', 'Golpes Digitais', 1, 'Empregos legitimos nao costumam exigir pagamento antecipado do candidato; esse padrao e frequentemente usado em fraudes.', 1, 2),
('Usar autenticacao biometrica (digital ou reconhecimento facial) elimina totalmente a necessidade de qualquer outra camada de seguranca.', 'Autenticação', 0, 'A biometria e um fator forte, mas idealmente deve ser combinada com outros mecanismos e boas praticas, ja que dados biometricos vazados nao podem ser ''trocados'' como uma senha.', 1, 2),
('Verificar se um aplicativo tem muitas avaliacoes negativas recentes reclamando de comportamento suspeito e uma boa pratica antes de instalar.', 'Downloads', 1, 'Avaliacoes recentes negativas podem indicar mudancas maliciosas em uma atualizacao do aplicativo, como insercao de anuncios abusivos ou coleta indevida de dados.', 1, 2),
('Redes sociais corporativas de uma empresa devem seguir as mesmas politicas de seguranca da informacao aplicadas aos demais sistemas.', 'Segurança Corporativa', 1, 'Contas corporativas em redes sociais tambem podem ser alvo de invasao e devem ter controles de acesso e senhas fortes como qualquer outro sistema.', 1, 2),
('Retirar o cartao de credito da carteira para ''aproximar'' e pagar por aproximacao (NFC) em uma maquina desconhecida na rua e sempre seguro.', 'Golpes Digitais', 0, 'Maquinas de pagamento fraudulentas ou adulteradas podem capturar dados do cartao; e recomendavel usar apenas maquinas em estabelecimentos confiaveis.', 1, 2),
('Manter a localizacao do celular ativada o tempo todo para todos os aplicativos, sem restricao, e uma boa pratica de privacidade.', 'Privacidade', 0, 'O ideal e conceder acesso a localizacao apenas aos aplicativos que realmente precisam, e preferencialmente apenas durante o uso.', 1, 2),
('Phishing direcionado a um cargo ou pessoa especifica dentro de uma empresa e chamado de spear phishing.', 'Phishing', 1, 'Diferente do phishing em massa, o spear phishing e personalizado com informacoes sobre a vitima para parecer mais convincente.', 1, 2),
('Ao encontrar um link acortado (como bit.ly) em uma mensagem, nao ha problema em clicar sem verificar o destino.', 'Links Maliciosos', 0, 'Links encurtados escondem o destino real; existem ferramentas para ''expandir'' o link e verificar para onde ele leva antes de clicar.', 1, 2),
('Notificacoes push falsas, imitando alertas de bancos, podem induzir o usuario a abrir um aplicativo falso e informar dados.', 'Golpes Digitais', 1, 'Alguns malwares para celular geram notificacoes falsas identicas as de bancos legitimos para roubar credenciais.', 1, 2),
('Um firewall ajuda a controlar quais conexoes de rede sao permitidas ou bloqueadas em um dispositivo.', 'Segurança em Redes Wi-Fi', 1, 'O firewall funciona como uma barreira de controle de trafego, permitindo ou negando comunicacoes com base em regras definidas.', 1, 2),
('Trocar de e-mail apos um vazamento de dados de um servico que voce usava e uma medida sempre necessaria e obrigatoria.', 'Vazamento de Dados', 0, 'Trocar a senha e habilitar 2FA costuma ser suficiente na maioria dos casos; trocar de e-mail e uma medida mais extrema, nao obrigatoria.', 1, 2),
('Verificar periodicamente quais aplicativos tem acesso a sua conta do Google ou Facebook ajuda a revogar acessos indevidos.', 'Privacidade', 1, 'Aplicativos de terceiros conectados a contas principais podem acumular permissoes esquecidas; revisa-las regularmente reduz riscos.', 1, 2),
('Um ataque de forca bruta tenta varias combinacoes de senha automaticamente até encontrar a correta.', 'Senhas', 1, 'Esse tipo de ataque usa softwares que testam milhares ou milhoes de combinacoes por segundo, por isso senhas longas e complexas dificultam o sucesso.', 1, 2),
('Enviar dados bancarios por mensagem de texto para uma pessoa que voce conheceu recentemente online, apos ela pedir com urgencia, e seguro.', 'Golpes Digitais', 0, 'Pedidos urgentes de dinheiro ou dados bancarios vindos de relacionamentos recentes online sao um padrao comum de golpes romanticos.', 1, 2),
('Verificar se um site usa certificado SSL valido (cadeado) e suficiente para garantir que uma loja online nunca e falsa.', 'Navegação Segura', 0, 'Certificados SSL sao faceis de obter e nao garantem a legitimidade da loja, apenas que a conexao com o servidor e criptografada.', 1, 2),
('Manter o Bluetooth do celular sempre visivel para todos os dispositivos proximos e uma boa pratica de seguranca.', 'Segurança em Dispositivos Móveis', 0, 'Deixar o Bluetooth visivel para todos aumenta o risco de tentativas de conexao indevida; o ideal e deixa-lo oculto quando nao estiver pareando um novo dispositivo.', 1, 2),
('Golpes de clonagem de WhatsApp costumam comecar com um pedido de codigo de verificacao recebido por SMS.', 'Golpes Digitais', 1, 'Ao obter o codigo de verificacao da vitima, o golpista consegue registrar o WhatsApp dela em outro aparelho e assumir a conta.', 1, 2),
('Aceitar solicitacoes de amizade de perfis desconhecidos sem verificar nada aumenta a exposicao a golpes de engenharia social.', 'Redes Sociais', 1, 'Perfis falsos usados em golpes costumam comecar interagindo como ''amigos'' para ganhar confianca antes de aplicar o golpe.', 1, 2),
('Manter o registro de quem acessou determinados sistemas (logs) e importante para identificar a origem de um incidente de seguranca.', 'Incidentes de Segurança', 1, 'Os logs de acesso permitem reconstruir o que aconteceu durante um incidente, auxiliando na investigacao e na resposta.', 1, 2),
('Um antivirus por si so garante proteção completa contra qualquer tipo de golpe, incluindo engenharia social.', 'Malware', 0, 'Antivirus protege contra malware conhecido, mas nao impede que a propria pessoa seja convencida a entregar dados voluntariamente em um golpe.', 1, 2),
('Ao usar um computador publico (lan house, biblioteca), e recomendado sempre sair (logout) de todas as contas antes de sair do local.', 'Boas Práticas de Segurança da Informação', 1, 'Nao encerrar a sessao em um computador publico pode permitir que a proxima pessoa acesse suas contas.', 1, 2),
('Empresas devem treinar periodicamente seus funcionarios sobre reconhecimento de phishing e engenharia social.', 'Segurança Corporativa', 1, 'O treinamento continuo reduz a chance de um funcionario cair em golpes, ja que o fator humano e um dos principais vetores de ataque.', 1, 2),
('Aplicativos de emprestimo falso, prometendo credito facil sem consulta ao SPC/Serasa, costumam pedir uma taxa antecipada como golpe.', 'Golpes Digitais', 1, 'Emprestimos legitimos nao cobram taxas antecipadas para ''liberar'' o credito; esse pedido e um forte indicio de fraude.', 1, 2),
('Verificar se o remetente de uma cobranca de streaming (como Netflix) e realmente o dominio oficial ajuda a evitar phishing.', 'Phishing', 1, 'Golpistas enviam falsas cobrancas de servicos populares de streaming para roubar dados de pagamento de quem clicar sem verificar.', 1, 2),
('Manter todos os dispositivos IoT (cameras, assistentes virtuais) com a senha padrao de fabrica facilita a manutencao.', 'Segurança em Dispositivos Móveis', 0, 'Senhas padrao de dispositivos IoT sao amplamente conhecidas e exploradas por atacantes para invadir redes domesticas ou espionar usuarios.', 1, 2),
('Verificar duas vezes o destinatario de um Pix antes de confirmar a transferencia e uma pratica recomendada, ja que a operacao e quase instantanea.', 'Boas Práticas de Segurança da Informação', 1, 'Diferente de outras formas de pagamento, o Pix e processado quase instantaneamente, dificultando o cancelamento em caso de erro ou fraude.', 1, 2),
('Manter conversas de trabalho sensiveis em grupos de WhatsApp pessoal, sem controle de seguranca corporativo, e uma boa pratica.', 'Segurança Corporativa', 0, 'Informacoes corporativas sensiveis devem tramitar por canais oficiais e controlados pela empresa, e nao por aplicativos pessoais sem gestao de seguranca.', 1, 2),
('Verificar remetente e assunto antes de baixar um anexo .zip ou .exe recebido por e-mail e uma pratica recomendada.', 'Downloads', 1, 'Arquivos executaveis (.exe) e compactados (.zip) sao formas comuns de distribuir malware disfarcado de documentos ou faturas.', 1, 2),
('Um ataque de ''man-in-the-middle'' ocorre quando um invasor intercepta a comunicacao entre duas partes sem que elas percebam.', 'Segurança em Redes Wi-Fi', 1, 'Esse tipo de ataque e comum em redes Wi-Fi publicas nao criptografadas, onde o atacante posiciona-se entre o usuario e o destino da conexao.', 1, 2),
('Compartilhar a tela do celular durante uma chamada de video com um ''suporte'' desconhecido, mostrando o aplicativo do banco, e seguro.', 'Golpes Digitais', 0, 'Mostrar a tela do banco durante uma chamada com um golpista disfarcado de suporte pode revelar saldo, senhas parciais e outros dados sensiveis.', 1, 2),
('Politicas de privacidade extensas e dificeis de entender sao, muitas vezes, um obstaculo intencional para que poucos usuarios as leiam.', 'Privacidade', 1, 'Criticos de privacidade apontam que a complexidade de alguns termos de uso desencoraja a leitura detalhada, dificultando o consentimento informado.', 1, 2),
('Verificar avaliacoes e reputacao de uma loja virtual antes da primeira compra ajuda a evitar golpes de e-commerce falso.', 'Golpes Digitais', 1, 'Lojas fraudulentas geralmente tem pouco tempo de existencia e reclamacoes recentes em sites de avaliacao de consumidores.', 1, 2),
('Instalar um segundo antivirus junto com o que ja esta no computador aumenta automaticamente a seguranca.', 'Malware', 0, 'Dois antivirus simultaneos podem conflitar entre si, causando lentidao ou falhas de deteccao, sem necessariamente aumentar a protecao real.', 1, 2),
('Ao usar redes sociais, e recomendado revisar periodicamente quem pode ver suas postagens e informacoes de perfil.', 'Redes Sociais', 1, 'Configuracoes de privacidade podem mudar apos atualizacoes da plataforma; revisa-las evita exposicao indesejada de conteudo.', 1, 2),
('Vazamentos de dados de senha costumam ser divulgados em sites que permitem verificar se um e-mail foi comprometido.', 'Vazamento de Dados', 1, 'Servicos como verificadores de vazamento permitem que o usuario saiba se seu e-mail apareceu em bases de dados roubadas, orientando a troca de senha.', 1, 2),
('Um dispositivo movel perdido ou roubado com bloqueio de tela ativado e criptografia de dados oferece mais proteção do que um sem nenhuma trava.', 'Segurança em Dispositivos Móveis', 1, 'O bloqueio de tela e a criptografia dificultam o acesso aos dados por quem encontrar ou roubar o aparelho.', 1, 2),
('A engenharia social so funciona contra pessoas com pouco conhecimento tecnico.', 'Engenharia Social', 0, 'A engenharia social explora emocoes humanas como medo, urgencia e confianca, podendo enganar ate profissionais experientes em tecnologia.', 1, 2),
('Verificar se o link de pagamento de um boleto ou carne recebido por WhatsApp aponta para o site oficial da empresa e uma boa pratica.', 'Golpes Digitais', 1, 'Links falsos de pagamento podem redirecionar o valor pago para uma conta fraudulenta em vez da empresa real.', 1, 2),
('Manter contas de redes sociais inativas por anos, sem excluir ou proteger, nao representa nenhum risco.', 'Redes Sociais', 0, 'Contas inativas e sem senha atualizada podem ser invadidas e usadas para golpes contra os contatos daquela pessoa.', 1, 2),
('Denunciar um perfil falso se passando por voce ou por uma empresa em redes sociais ajuda a proteger outras pessoas do golpe.', 'Redes Sociais', 1, 'A denuncia pode levar a remocao do perfil falso, reduzindo o alcance do golpista e protegendo outros usuarios.', 1, 2),
('A recuperacao de senha por perguntas secretas e sempre mais segura do que a recuperacao por e-mail ou SMS.', 'Autenticação', 0, 'Perguntas secretas podem ter respostas descobriveis publicamente; a seguranca depende do metodo escolhido e nao ha garantia de que perguntas secretas sejam superiores.', 1, 2),
('Verificar se uma vaga de emprego remoto exige a compra de equipamentos proprios como pre-requisito para ''garantir a vaga'' e um sinal de alerta.', 'Golpes Digitais', 1, 'Pedir que o candidato compre equipamentos antes de comecar a trabalhar, sem contrato formal, e um padrao comum em fraudes de emprego.', 1, 2),
('Times de resposta a incidentes (CSIRT) sao responsaveis por identificar, conter e remediar problemas de seguranca em uma organizacao.', 'Incidentes de Segurança', 1, 'Esses times coordenam a resposta tecnica e organizacional durante e apos um incidente de seguranca.', 1, 2),
('O protocolo HTTPS utiliza TLS para criptografar os dados trocados entre o navegador e o servidor.', 'Navegação Segura', 1, 'O TLS (Transport Layer Security) e responsavel por criptografar a comunicacao, protegendo contra interceptacao e adulteracao dos dados em transito.', 1, 3),
('Um ataque de ''SIM swap'' permite que um criminoso transfira o numero de telefone da vitima para um chip proprio, interceptando SMS de autenticacao.', 'Autenticação Multifator', 1, 'Ao convencer a operadora a portar o numero, o atacante passa a receber os codigos de verificacao por SMS destinados a vitima.', 1, 3),
('Hashing de senhas e o mesmo que criptografia reversivel, entao uma senha ''hasheada'' pode sempre ser recuperada em texto puro pelo sistema.', 'Senhas', 0, 'Hashing e uma funcao unidirecional; um sistema bem projetado nunca deveria conseguir ''reverter'' um hash para a senha original, apenas compara-lo com um novo hash gerado no login.', 1, 3),
('O uso de ''salt'' no armazenamento de senhas ajuda a impedir ataques de rainbow table.', 'Senhas', 1, 'O salt adiciona um valor aleatorio unico a cada senha antes do hashing, tornando inuteis tabelas pre-computadas de hashes conhecidos.', 1, 3),
('Um ataque de ''phishing'' que usa chamadas de voz, em vez de e-mail ou SMS, e chamado de vishing.', 'Phishing', 1, 'Vishing (voice phishing) usa ligacoes telefonicas, muitas vezes com numeros falsificados (spoofing), para induzir a vitima a fornecer dados.', 1, 3),
('Uma VPN (Virtual Private Network) cria um tunel criptografado entre o dispositivo do usuario e um servidor remoto.', 'Segurança em Redes Wi-Fi', 1, 'O tunel criptografado protege o trafego contra interceptacao, especialmente util em redes publicas nao confiaveis.', 1, 3),
('Ataques de ''DNS spoofing'' redirecionam o usuario para um site falso mesmo que ele digite o endereco correto do site verdadeiro.', 'Navegação Segura', 1, 'Ao corromper a resolucao de nomes (DNS), o atacante faz o dominio legitimo apontar para um servidor malicioso controlado por ele.', 1, 3),
('Um ''zero-day'' e uma vulnerabilidade conhecida ha muito tempo e ja corrigida por todos os fabricantes.', 'Malware', 0, 'Um zero-day e uma falha ainda desconhecida pelo fabricante (ou sem correcao disponivel) no momento em que e explorada por um atacante.', 1, 3),
('Engenharia social do tipo ''pretexting'' envolve a criacao de um cenario ou identidade falsa para obter informacoes da vitima.', 'Engenharia Social', 1, 'No pretexting, o atacante inventa uma historia convincente (ex: se passar por auditor ou tecnico) para justificar o pedido de dados.', 1, 3),
('O principio do ''menor privilegio'' recomenda que usuarios e sistemas tenham apenas as permissoes minimas necessarias para suas funcoes.', 'Segurança Corporativa', 1, 'Esse principio reduz o impacto de uma conta comprometida, ja que o acesso do atacante fica limitado ao que a conta invadida podia acessar.', 1, 3),
('Um keylogger e um tipo de malware que registra as teclas digitadas pelo usuario, podendo capturar senhas e dados sensiveis.', 'Malware', 1, 'Keyloggers monitoram a entrada do teclado silenciosamente e enviam os dados capturados ao atacante.', 1, 3),
('Certificados digitais autoassinados oferecem o mesmo nivel de confianca que certificados emitidos por uma autoridade certificadora reconhecida.', 'Navegação Segura', 0, 'Certificados autoassinados nao passam pela validacao de uma autoridade certificadora confiavel, tornando mais dificil verificar a autenticidade do site.', 1, 3),
('A segmentacao de rede em uma empresa ajuda a limitar o alcance de um atacante caso um dispositivo seja comprometido.', 'Segurança Corporativa', 1, 'Ao dividir a rede em segmentos isolados, um invasor que comprometa um segmento tem dificuldade de acessar diretamente outros setores criticos.', 1, 3),
('Um ataque de ''credential stuffing'' usa listas de senhas vazadas de outros servicos para tentar login em massa em contas diferentes.', 'Senhas', 1, 'Esse ataque explora o fato de que muitas pessoas reutilizam a mesma senha em varios servicos, testando credenciais vazadas em outras plataformas.', 1, 3),
('O termo ''malvertising'' se refere a anuncios legitimos que, por engano, direcionam o usuario para paginas educativas de seguranca.', 'Malware', 0, 'Malvertising e a distribuicao de malware ou redirecionamento malicioso por meio de anuncios online, muitas vezes em sites legitimos comprometidos.', 1, 3),
('Um ataque de ''business email compromise'' (BEC) geralmente envolve a falsificacao ou invasao de contas de e-mail corporativas para fraudar pagamentos.', 'Segurança Corporativa', 1, 'No BEC, o atacante se passa por um executivo ou fornecedor legitimo para induzir a vitima a realizar transferencias financeiras fraudulentas.', 1, 3),
('A autenticacao multifator baseada em token fisico (como uma chave U2F) e considerada mais resistente a phishing do que codigos enviados por SMS.', 'Autenticação Multifator', 1, 'Chaves fisicas de seguranca verificam a origem da solicitacao de login, dificultando o uso do codigo em um site de phishing, o que nao ocorre com SMS.', 1, 3),
('Um ''honeypot'' e um sistema criado intencionalmente vulneravel para atrair e estudar o comportamento de atacantes.', 'Incidentes de Segurança', 1, 'Honeypots ajudam equipes de seguranca a identificar tecnicas de ataque e coletar inteligencia sobre ameacas sem expor sistemas reais.', 1, 3),
('Criptografar um disco inteiro (full disk encryption) protege os dados apenas quando o dispositivo esta ligado e desbloqueado.', 'Segurança em Dispositivos Móveis', 0, 'A criptografia de disco protege os dados justamente quando o dispositivo esta desligado ou bloqueado, impedindo o acesso sem a chave/senha correta.', 1, 3),
('Um ataque de ''watering hole'' compromete um site que a vitima costuma visitar, em vez de atacar a vitima diretamente.', 'Malware', 1, 'O atacante identifica sites frequentados pelo grupo-alvo e os compromete, esperando que as vitimas visitem e sejam infectadas indiretamente.', 1, 3),
('Politicas de retencao de dados definem por quanto tempo uma organizacao deve manter ou eliminar informacoes coletadas.', 'Vazamento de Dados', 1, 'Manter dados por mais tempo do que o necessario aumenta o impacto potencial de um vazamento, por isso politicas de retencao sao importantes.', 1, 3),
('O ''typosquatting'' consiste em registrar dominios com erros de digitacao proximos a sites populares para enganar usuarios.', 'Phishing', 1, 'Exemplo: registrar ''gogle.com'' esperando que usuarios digitem errado o endereco de um site popular e caiam em uma pagina falsa.', 1, 3),
('Ransomware do tipo ''double extortion'' apenas criptografa os arquivos, sem ameacar divulgar dados roubados.', 'Ransomware', 0, 'Na extorsao dupla, alem de criptografar os arquivos, o atacante tambem rouba dados e ameaca publica-los caso o resgate nao seja pago.', 1, 3),
('A analise de logs de seguranca (SIEM) ajuda a correlacionar eventos de diferentes sistemas para identificar padroes de ataque.', 'Segurança Corporativa', 1, 'Ferramentas de SIEM agregam e analisam logs de multiplas fontes, permitindo detectar comportamentos anomalos que indicam um possivel ataque.', 1, 3),
('Um ''ataque de forca bruta com lista de dicionario'' testa senhas comuns e palavras conhecidas em vez de todas as combinacoes possiveis.', 'Senhas', 1, 'Esse metodo e mais rapido do que a forca bruta pura, pois prioriza palavras e padroes frequentemente usados como senha.', 1, 3),
('Aplicativos que solicitam permissao de ''acessibilidade'' no Android podem, quando maliciosos, ler a tela e simular toques no dispositivo.', 'Segurança em Dispositivos Móveis', 1, 'Trojans bancarios para Android abusam da permissao de acessibilidade para roubar dados exibidos na tela e realizar acoes automaticas sem o consentimento do usuario.', 1, 3),
('O conceito de ''defesa em profundidade'' recomenda depender de uma unica camada de seguranca muito robusta, em vez de multiplas camadas.', 'Segurança Corporativa', 0, 'A defesa em profundidade recomenda multiplas camadas de seguranca independentes, para que a falha de uma nao comprometa todo o sistema.', 1, 3),
('Um ataque de ''clickjacking'' engana o usuario para clicar em algo diferente do que ele acredita estar clicando, usando camadas invisiveis na pagina.', 'Navegação Segura', 1, 'O atacante sobrepoe elementos invisiveis sobre botoes legitimos, fazendo o clique do usuario acionar uma acao maliciosa sem que ele perceba.', 1, 3),
('A criptografia simetrica usa a mesma chave para cifrar e decifrar os dados, enquanto a assimetrica usa um par de chaves publica e privada.', 'Boas Práticas de Segurança da Informação', 1, 'Essa e a distincao fundamental entre os dois principais modelos de criptografia usados em seguranca da informacao.', 1, 3),
('O termo ''shoulder surfing'' se refere a observar por cima do ombro de alguem para capturar senhas ou informacoes digitadas.', 'Engenharia Social', 1, 'E uma tecnica simples de coleta de informacao usada em locais publicos, como caixas eletronicos e transporte publico.', 1, 3),
('Um teste de invasao (pentest) autorizado tem como objetivo identificar vulnerabilidades antes que atacantes reais as explorem.', 'Segurança Corporativa', 1, 'Pentests simulam ataques reais, de forma controlada e autorizada, para avaliar a seguranca de sistemas e redes.', 1, 3),
('Um ''ataque de repeticao'' (replay attack) reenvia uma comunicacao capturada anteriormente para tentar repetir uma acao, como uma transacao.', 'Segurança em Redes Wi-Fi', 1, 'Se o sistema nao usar mecanismos como tokens de uso unico ou timestamps, o atacante pode reenviar dados capturados para repetir uma acao valida.', 1, 3),
('A verificacao de integridade de arquivos por hash (como SHA-256) e usada apenas para criptografar senhas, nunca para verificar arquivos.', 'Boas Práticas de Segurança da Informação', 0, 'Funcoes de hash como SHA-256 tambem sao amplamente usadas para verificar se um arquivo baixado nao foi alterado, comparando o hash divulgado com o calculado.', 1, 3),
('Golpes de ''romance scam'' costumam envolver relacionamentos falsos construidos ao longo de semanas ou meses antes de pedir dinheiro.', 'Golpes Digitais', 1, 'O investimento de tempo cria confianca emocional na vitima, tornando o pedido de dinheiro posterior mais convincente.', 1, 3),
('Um ''ataque de negacao de servico'' (DoS) tem como objetivo roubar dados sigilosos de um servidor.', 'Incidentes de Segurança', 0, 'O objetivo de um ataque DoS/DDoS e tornar um servico indisponivel sobrecarregando-o com trafego, e nao necessariamente roubar dados.', 1, 3),
('A pratica de ''least exposure'' (menor exposicao) recomenda desativar servicos e portas de rede que nao sao necessarios para o funcionamento do sistema.', 'Segurança Corporativa', 1, 'Reduzir a superficie de ataque desativando servicos desnecessarios diminui o numero de pontos que um atacante pode explorar.', 1, 3),
('Malwares do tipo ''trojan bancario'' costumam se disfarcar de aplicativos legitimos para roubar credenciais de acesso a contas financeiras.', 'Malware', 1, 'Esses trojans imitam a interface de aplicativos de bancos ou interceptam a comunicacao para capturar login e senha da vitima.', 1, 3),
('Um ''ataque de engenharia social inversa'' ocorre quando o atacante faz a vitima acreditar que precisa da ajuda dele, e nao o contrario.', 'Engenharia Social', 1, 'Nesse tipo de ataque, o criminoso cria um problema (real ou falso) e depois se oferece como a ''solucao'', ganhando acesso ou confianca da vitima.', 1, 3),
('O conceito de ''shadow IT'' se refere ao uso de aplicativos e servicos de TI nao aprovados pelo departamento de tecnologia de uma empresa.', 'Segurança Corporativa', 1, 'Ferramentas usadas sem aprovacao ou conhecimento da equipe de TI escapam dos controles de seguranca corporativos, aumentando riscos.', 1, 3),
('Cookies de sessao roubados por meio de um ataque de ''cross-site scripting'' (XSS) podem permitir que um atacante assuma a sessao logada da vitima.', 'Navegação Segura', 1, 'Se um site vulneravel a XSS permitir a execucao de scripts maliciosos, o atacante pode capturar cookies de sessao e se autenticar como a vitima sem saber a senha.', 1, 3),
('A ''exfiltracao de dados'' se refere ao processo legitimo de backup de dados corporativos para a nuvem.', 'Vazamento de Dados', 0, 'Exfiltracao de dados se refere a transferencia nao autorizada de informacoes para fora da organizacao, geralmente por um atacante ou ameaca interna.', 1, 3),
('Um ''insider threat'' (ameaca interna) e um risco de seguranca originado por alguem com acesso legitimo, como um funcionario ou ex-funcionario.', 'Segurança Corporativa', 1, 'Ameacas internas podem ser intencionais (funcionario mal-intencionado) ou acidentais (erro humano), e sao dificeis de detectar por ja terem acesso autorizado.', 1, 3),
('Backups em nuvem sao imunes a ataques de ransomware, pois nunca podem ser criptografados por um atacante.', 'Backups', 0, 'Se o backup em nuvem estiver sincronizado continuamente e acessivel com as mesmas credenciais comprometidas, ele tambem pode ser criptografado ou apagado pelo atacante; backups imutaveis ou com versoes anteriores reduzem esse risco.', 1, 3),
('O ''principio de separacao de deveres'' busca evitar que uma unica pessoa tenha controle total sobre um processo critico, reduzindo fraudes.', 'Segurança Corporativa', 1, 'Dividir etapas criticas entre diferentes pessoas (como quem autoriza e quem executa um pagamento) reduz o risco de fraude ou erro nao detectado.', 1, 3),
('Um ataque de ''password spraying'' testa uma unica senha comum em muitas contas diferentes, em vez de varias senhas na mesma conta.', 'Senhas', 1, 'Essa abordagem evita o bloqueio por tentativas excessivas em uma unica conta, testando poucas senhas populares em muitos usuarios.', 1, 3),
('Dispositivos moveis corporativos gerenciados por uma solucao de MDM (Mobile Device Management) permitem aplicar politicas de seguranca remotamente.', 'Segurança em Dispositivos Móveis', 1, 'Solucoes de MDM permitem, por exemplo, forcar criptografia, exigir senha e apagar dados remotamente em caso de perda ou roubo do aparelho.', 1, 3),
('Auditorias periodicas de seguranca da informacao servem apenas para cumprir exigencias burocraticas, sem valor pratico real.', 'Segurança Corporativa', 0, 'Auditorias identificam falhas de controle, nao conformidades e oportunidades de melhoria, contribuindo diretamente para reduzir riscos reais.', 1, 3),
('O conceito de ''superficie de ataque'' se refere ao conjunto de pontos por onde um sistema pode ser potencialmente atacado.', 'Incidentes de Segurança', 1, 'Quanto mais servicos, portas e funcionalidades expostas, maior a superficie de ataque e o numero de vetores possiveis de invasao.', 1, 3),
('Um plano de resposta a incidentes deve incluir apenas as etapas tecnicas de correcao, sem envolver comunicacao ou aspectos legais.', 'Incidentes de Segurança', 0, 'Um plano de resposta completo inclui deteccao, contencao, erradicacao, recuperacao, comunicacao com partes interessadas e, quando aplicavel, aspectos legais e regulatorios.', 1, 3),
('Ataques de ''drive-by download'' instalam malware no dispositivo apenas por visitar um site comprometido, sem necessidade de clique adicional.', 'Malware', 1, 'Esses ataques exploram vulnerabilidades do navegador ou de plugins para instalar malware automaticamente ao carregar a pagina maliciosa.', 1, 3),
('A LGPD (Lei Geral de Protecao de Dados) se aplica apenas a empresas de tecnologia, nao a qualquer organizacao que trate dados pessoais no Brasil.', 'Vazamento de Dados', 0, 'A LGPD se aplica a qualquer pessoa ou organizacao, publica ou privada, que realize tratamento de dados pessoais no Brasil, independente do setor.', 1, 3),
('O uso de listas de bloqueio (blacklists) de IPs e dominios maliciosos e uma medida complementar, mas nao substitui outras camadas de seguranca.', 'Segurança Corporativa', 1, 'Listas de bloqueio ajudam a filtrar ameacas conhecidas, mas nao detectam ataques novos ou desconhecidos, por isso devem ser combinadas com outras defesas.', 1, 3),
('Um ''ataque de downgrade'' forca uma conexao a usar um protocolo de seguranca mais antigo e vulneravel, em vez do mais moderno e seguro.', 'Navegação Segura', 1, 'Ao forcar o uso de versoes antigas de TLS/SSL, por exemplo, o atacante explora vulnerabilidades conhecidas que ja foram corrigidas em versoes mais recentes.', 1, 3),
('Aplicativos com criptografia de ponta a ponta impedem completamente que a propria empresa que os fornece acesse o conteudo das mensagens.', 'Privacidade', 1, 'Na criptografia de ponta a ponta bem implementada, apenas os dispositivos dos usuarios envolvidos possuem as chaves necessarias para decifrar o conteudo.', 1, 3),
('A classificacao de dados (publico, interno, confidencial, restrito) ajuda a definir quais controles de seguranca aplicar a cada tipo de informacao.', 'Segurança Corporativa', 1, 'Classificar dados permite priorizar recursos de seguranca para as informacoes mais sensiveis, em vez de tratar tudo com o mesmo nivel de protecao.', 1, 3),
('Um ''ataque de pharming'' redireciona usuarios para sites falsos manipulando o sistema de nomes de dominio ou o arquivo hosts do dispositivo.', 'Phishing', 1, 'Diferente do phishing tradicional, o pharming nao depende de um clique em link malicioso; a redirecao ocorre no nivel de rede ou do proprio dispositivo.', 1, 3),
('O termo ''ataque supply chain'' se refere a comprometer um fornecedor ou componente de terceiros para atingir indiretamente o alvo final.', 'Incidentes de Segurança', 1, 'Ao comprometer um software ou fornecedor amplamente utilizado, o atacante pode atingir muitas organizacoes que dependem daquele componente.', 1, 3),
('Um ataque de ''baiting'' (isca) fisica pode envolver deixar um pendrive infectado em um local publico da empresa, na esperanca de que um funcionario o conecte por curiosidade.', 'Engenharia Social', 1, 'Essa tecnica explora a curiosidade humana; ao conectar o pendrive, o funcionario pode executar, sem saber, um malware programado para rodar automaticamente.', 1, 3),
('Tokens de sessao (session tokens) que nao expiram nunca representam um risco de seguranca menor do que tokens com tempo de expiracao curto.', 'Autenticação', 0, 'Tokens sem expiracao permanecem validos indefinidamente se roubados, aumentando o tempo em que um atacante pode usa-los; tokens com expiracao curta limitam essa janela de risco.', 1, 3),
('Redes ''VLAN'' (Virtual Local Area Network) podem ser usadas para segmentar logicamente uma rede fisica em multiplos dominios de broadcast isolados.', 'Segurança em Redes Wi-Fi', 1, 'VLANs permitem dividir uma mesma infraestrutura fisica em redes logicas separadas, contribuindo para a segmentacao e o isolamento de trafego sensivel.', 1, 3),
('O algoritmo RSA e um exemplo de criptografia assimetrica baseado na dificuldade de fatorar numeros grandes em seus fatores primos.', 'Boas Práticas de Segurança da Informação', 1, 'A seguranca do RSA depende da complexidade computacional de fatorar o produto de dois numeros primos grandes.', 1, 4),
('O protocolo Perfect Forward Secrecy (PFS) garante que, mesmo se a chave privada de longo prazo for comprometida no futuro, sessoes passadas nao possam ser descriptografadas.', 'Navegação Segura', 1, 'O PFS gera chaves de sessao unicas e efemeras para cada conexao, entao a exposicao futura da chave privada nao compromete o trafego ja registrado anteriormente.', 1, 4),
('Um ataque de ''padding oracle'' explora informacoes vazadas pelo comportamento de erro de um esquema de criptografia com preenchimento (padding) mal implementado.', 'Boas Práticas de Segurança da Informação', 1, 'Ao observar diferencas em mensagens de erro ou tempo de resposta relacionadas ao padding, o atacante pode inferir informacoes sobre o texto cifrado.', 1, 4),
('O framework MITRE ATT&CK cataloga taticas e tecnicas conhecidas utilizadas por atacantes durante o ciclo de vida de uma intrusao.', 'Incidentes de Segurança', 1, 'O ATT&CK e amplamente usado por equipes de seguranca para mapear comportamentos observados de atacantes e melhorar deteccao e resposta.', 1, 4),
('Um ataque de ''golden ticket'' em ambientes Active Directory (Kerberos) explora o comprometimento da conta KRBTGT para forjar tickets de autenticacao com privilegios arbitrarios.', 'Segurança Corporativa', 1, 'Com o hash da conta KRBTGT, um atacante pode gerar tickets Kerberos validos para se autenticar como qualquer usuario, incluindo administradores de dominio.', 1, 4),
('Uma vulnerabilidade de ''buffer overflow'' ocorre quando um programa escreve mais dados em uma area de memoria do que ela pode armazenar, podendo sobrescrever memoria adjacente.', 'Malware', 1, 'Essa sobrescrita pode ser explorada para alterar o fluxo de execucao do programa, permitindo a execucao de codigo arbitrario controlado pelo atacante.', 1, 4),
('Tecnicas de ''ASLR'' (Address Space Layout Randomization) tornam mais dificil a exploracao de vulnerabilidades de memoria ao randomizar os enderecos usados pelo processo.', 'Malware', 1, 'Ao dificultar a previsao de enderecos de memoria, o ASLR complica a exploracao confiavel de vulnerabilidades como buffer overflow.', 1, 4),
('Um ataque de ''living off the land'' utiliza apenas ferramentas e binarios legitimos ja presentes no sistema operacional para evitar deteccao por antivirus.', 'Malware', 1, 'Ao usar ferramentas nativas do sistema (como PowerShell ou WMI) em vez de malware customizado, o atacante reduz a chance de ser identificado por assinaturas conhecidas.', 1, 4),
('O conceito de ''lateral movement'' descreve a etapa em que um atacante, ja dentro da rede, se desloca de um sistema comprometido para outros sistemas internos.', 'Segurança Corporativa', 1, 'Apos o acesso inicial, o atacante busca ampliar seu alcance dentro da rede, frequentemente visando sistemas com privilegios mais altos.', 1, 4),
('Uma assinatura digital baseada em criptografia assimetrica garante autenticidade e integridade, mas nunca pode ser usada para verificar nao-repudio.', 'Boas Práticas de Segurança da Informação', 0, 'Uma das principais propriedades da assinatura digital e justamente garantir o nao-repudio, pois apenas o detentor da chave privada correspondente poderia ter gerado aquela assinatura.', 1, 4),
('O ''Certificate Transparency'' e um mecanismo publico que registra a emissao de certificados digitais para permitir a deteccao de certificados fraudulentos.', 'Navegação Segura', 1, 'Ao manter logs publicos e auditaveis de certificados emitidos, e possivel detectar emissoes indevidas ou fraudulentas por autoridades certificadoras comprometidas.', 1, 4),
('Um ataque de ''timing side-channel'' explora variacoes no tempo de execucao de uma operacao criptografica para inferir informacoes sobre a chave secreta.', 'Boas Práticas de Segurança da Informação', 1, 'Pequenas diferencas no tempo de processamento, dependendo dos dados de entrada, podem revelar informacoes sensiveis sobre chaves criptograficas se a implementacao nao for constante em tempo.', 1, 4),
('Vulnerabilidades de ''SSRF'' (Server-Side Request Forgery) permitem que um atacante faca um servidor realizar requisicoes para destinos nao intencionados, potencialmente acessando recursos internos.', 'Segurança Corporativa', 1, 'Isso pode ser usado para acessar metadados de servicos em nuvem, sistemas internos protegidos por firewall, ou outros recursos que nao deveriam ser expostos diretamente.', 1, 4),
('O modelo de seguranca ''Zero Trust'' assume que qualquer dispositivo ou usuario dentro do perimetro de rede corporativo e automaticamente confiavel.', 'Segurança Corporativa', 0, 'O Zero Trust parte do principio contrario: nenhum usuario ou dispositivo e confiavel por padrao, mesmo dentro do perimetro, exigindo verificacao continua de identidade e contexto.', 1, 4),
('Ataques de ''DLL hijacking'' exploram a ordem de busca de bibliotecas dinamicas do sistema operacional para fazer um programa legitimo carregar uma DLL maliciosa.', 'Malware', 1, 'Ao colocar uma DLL maliciosa com nome identico em um local pesquisado antes do local legitimo, o atacante faz o programa carregar seu codigo sem alterar o executavel original.', 1, 4),
('Um ''ataque de reflexao'' em amplificacao DDoS explora servicos que respondem a requisicoes com pacotes de resposta muito maiores do que a requisicao original.', 'Incidentes de Segurança', 1, 'Servicos como DNS ou NTP mal configurados podem ser abusados para amplificar o volume de trafego direcionado a vitima, usando enderecos IP falsificados (spoofed).', 1, 4),
('A tecnica de ''certificate pinning'' em aplicativos moveis ajuda a prevenir ataques de man-in-the-middle mesmo quando um certificado fraudulento e aceito pelo sistema.', 'Segurança em Dispositivos Móveis', 1, 'O pinning faz o aplicativo verificar se o certificado apresentado corresponde exatamente ao esperado, e nao apenas se e valido segundo uma autoridade certificadora generica.', 1, 4),
('Um IOC (Indicator of Compromise) e uma evidencia observavel, como um hash de arquivo ou endereco IP, que sugere que um sistema foi comprometido.', 'Incidentes de Segurança', 1, 'IOCs sao usados por equipes de seguranca para detectar e responder a atividades maliciosas conhecidas em uma rede ou sistema.', 1, 4),
('Tecnicas de ''threat hunting'' se baseiam exclusivamente em alertas automaticos gerados por ferramentas, sem qualquer investigacao humana proativa.', 'Incidentes de Segurança', 0, 'O threat hunting envolve a busca proativa e manual por ameacas que podem ter escapado das deteccoes automatizadas, combinando hipoteses, dados e experiencia humana.', 1, 4),
('Um ataque de ''race condition'' explora o momento entre a verificacao de uma condicao e o uso do recurso (TOCTOU) para causar um comportamento inesperado no sistema.', 'Malware', 1, 'Time-of-check to time-of-use (TOCTOU) e uma classe classica de vulnerabilidade onde o estado do sistema muda entre a verificacao e a execucao da acao.', 1, 4),
('O uso de ''HSTS'' (HTTP Strict Transport Security) instrui o navegador a sempre se conectar a um site via HTTPS, mesmo que o usuario digite HTTP.', 'Navegação Segura', 1, 'O HSTS ajuda a prevenir ataques de downgrade que tentam forcar a conexao a usar HTTP nao criptografado.', 1, 4),
('Um ''container'' (como Docker) oferece isolamento identico ao de uma maquina virtual completa, tornando irrelevante a seguranca do kernel do host.', 'Segurança Corporativa', 0, 'Containers compartilham o kernel do sistema host, entao uma vulnerabilidade no kernel ou uma configuracao incorreta pode permitir escapar do isolamento do container, diferente do isolamento mais forte de uma VM completa.', 1, 4),
('Um ataque de ''DNS tunneling'' pode ser usado para exfiltrar dados de uma rede corporativa disfarcando o trafego como consultas DNS legitimas.', 'Vazamento de Dados', 1, 'Como o trafego DNS costuma ser menos monitorado, atacantes podem codificar dados dentro de consultas e respostas DNS para contornar controles de seguranca.', 1, 4),
('O conceito de ''blast radius'' em seguranca se refere ao alcance potencial de dano que um unico ponto de falha ou credencial comprometida pode causar.', 'Segurança Corporativa', 1, 'Reduzir o blast radius, por exemplo com segmentacao e menor privilegio, limita o impacto de um unico comprometimento na infraestrutura como um todo.', 1, 4),
('Vulnerabilidades de ''deserializacao insegura'' podem permitir a execucao remota de codigo quando dados nao confiaveis sao convertidos de volta em objetos pela aplicacao.', 'Malware', 1, 'Se a aplicacao desserializar dados controlados pelo atacante sem validacao adequada, isso pode ser explorado para instanciar objetos maliciosos e executar codigo arbitrario.', 1, 4),
('A tecnica de ''fuzzing'' consiste em fornecer entradas aleatorias ou malformadas a um programa para descobrir falhas e vulnerabilidades.', 'Segurança Corporativa', 1, 'O fuzzing automatizado testa exaustivamente entradas inesperadas, ajudando a identificar bugs de seguranca antes que sejam explorados maliciosamente.', 1, 4),
('Um ''rootkit'' e projetado para ocultar sua propria presenca e a de outros processos maliciosos, dificultando a deteccao pelo sistema operacional ou antivirus.', 'Malware', 1, 'Rootkits podem operar em niveis profundos do sistema, como kernel ou firmware, interceptando chamadas para esconder arquivos, processos e conexoes maliciosas.', 1, 4),
('O ''CVSS'' (Common Vulnerability Scoring System) fornece uma pontuacao padronizada para medir a severidade tecnica de uma vulnerabilidade.', 'Incidentes de Segurança', 1, 'O CVSS considera fatores como vetor de ataque, complexidade e impacto para gerar uma pontuacao comparavel entre diferentes vulnerabilidades.', 1, 4),
('Ataques de ''cache poisoning'' inserem dados falsos em um cache (como DNS ou CDN) para que futuras requisicoes recebam conteudo malicioso ou incorreto.', 'Navegação Segura', 1, 'Ao corromper as respostas armazenadas em cache, o atacante pode fazer com que multiplos usuarios recebam conteudo malicioso sem interagir diretamente com cada um deles.', 1, 4),
('A criptoanalise diferencial e uma tecnica usada exclusivamente para melhorar o desempenho de algoritmos de compressao de dados.', 'Boas Práticas de Segurança da Informação', 0, 'A criptoanalise diferencial e uma tecnica usada para analisar cifras de bloco, estudando como diferencas na entrada afetam diferencas na saida, buscando fraquezas no algoritmo.', 1, 4),
('Um ''ataque de canal lateral'' pode explorar consumo de energia, emissao eletromagnetica ou som de um dispositivo para extrair informacoes sobre chaves criptograficas.', 'Boas Práticas de Segurança da Informação', 1, 'Esses ataques nao exploram falhas logicas do algoritmo, mas caracteristicas fisicas da implementacao em hardware durante a execucao das operacoes criptograficas.', 1, 4),
('O ''principio de Kerckhoffs'' afirma que a seguranca de um sistema criptografico deve depender do segredo do algoritmo, e nao apenas da chave.', 'Boas Práticas de Segurança da Informação', 0, 'O principio de Kerckhoffs afirma o contrario: um sistema deve permanecer seguro mesmo que todos os detalhes do algoritmo sejam publicos, desde que a chave permaneca secreta.', 1, 4),
('Um ataque de ''privilege escalation vertical'' ocorre quando um usuario com privilegios limitados consegue obter permissoes de administrador ou root.', 'Segurança Corporativa', 1, 'Diferente da escalada horizontal (acessar outra conta de mesmo nivel), a vertical busca elevar o proprio nivel de privilegio no sistema.', 1, 4),
('Um WAF (Web Application Firewall) e capaz de substituir completamente a necessidade de corrigir vulnerabilidades no codigo da aplicacao.', 'Segurança Corporativa', 0, 'O WAF e uma camada de proteção complementar que filtra trafego malicioso conhecido, mas nao corrige a causa raiz de vulnerabilidades no codigo, que devem ser tratadas via correcao (patching).', 1, 4),
('Ataques de ''session fixation'' forcam a vitima a usar um identificador de sessao predefinido pelo atacante, que depois pode ser usado para assumir a sessao autenticada.', 'Navegação Segura', 1, 'Se a aplicacao nao gerar um novo identificador de sessao apos o login, o atacante que definiu o ID original pode usa-lo para acessar a sessao ja autenticada da vitima.', 1, 4),
('O modelo de maturidade C2M2 e usado exclusivamente para avaliar a seguranca fisica de data centers, sem relacao com processos de seguranca da informacao.', 'Segurança Corporativa', 0, 'Modelos de maturidade em ciberseguranca (como o C2M2) avaliam processos, governanca e capacidades organizacionais de gestao de risco ciberneticos, nao apenas seguranca fisica.', 1, 4),
('A tecnica de ''domain fronting'' pode ser usada por atacantes para disfarcar o trafego de comando e controle, fazendo-o parecer destinado a um servico legitimo e confiavel.', 'Malware', 1, 'Ao usar a infraestrutura de grandes provedores de nuvem/CDN, o trafego malicioso se mistura ao trafego legitimo, dificultando o bloqueio baseado em dominio.', 1, 4),
('Um ''ataque de reutilizacao de nonce'' em criptografia pode comprometer a confidencialidade de mensagens cifradas quando o mesmo valor de nonce e usado mais de uma vez com a mesma chave.', 'Boas Práticas de Segurança da Informação', 1, 'Muitos esquemas de criptografia moderna exigem nonces unicos por mensagem; a reutilizacao pode permitir a um atacante recuperar informacoes sobre o texto claro ou a chave.', 1, 4),
('A segregacao entre ambientes de desenvolvimento, homologacao e producao ajuda a evitar que falhas ou testes inseguros afetem diretamente os dados reais dos usuarios.', 'Segurança Corporativa', 1, 'Manter ambientes separados reduz o risco de que codigo instavel, dados de teste ou configuracoes incorretas impactem o sistema em producao.', 1, 4),
('Um ataque de ''command injection'' ocorre quando entradas do usuario sao incorporadas sem validacao a comandos executados diretamente pelo sistema operacional.', 'Malware', 1, 'Se a aplicacao concatenar entradas do usuario em comandos do shell sem sanitizacao, um atacante pode injetar comandos adicionais que serao executados pelo sistema.', 1, 4),
('O framework de ''Cyber Kill Chain'' descreve as etapas sequenciais tipicas de um ataque ciberneticos, do reconhecimento inicial a acao final sobre o objetivo.', 'Incidentes de Segurança', 1, 'Esse modelo, criado pela Lockheed Martin, ajuda equipes de defesa a identificar em qual estagio um ataque se encontra e como interrompe-lo.', 1, 4),
('Chaves criptograficas de curva eliptica (ECC) geralmente oferecem seguranca equivalente ao RSA usando tamanhos de chave significativamente menores.', 'Boas Práticas de Segurança da Informação', 1, 'A ECC e considerada mais eficiente computacionalmente, permitindo chaves menores com nivel de seguranca comparavel ao RSA de chaves muito maiores.', 1, 4),
('Um ''ataque de poisoning'' contra modelos de machine learning envolve manipular os dados de treinamento para comprometer o comportamento futuro do modelo.', 'Incidentes de Segurança', 1, 'Ao inserir dados maliciosos ou tendenciosos no conjunto de treinamento, um atacante pode fazer o modelo aprender comportamentos indesejados ou vulneraveis.', 1, 4),
('A auditoria de codigo-fonte estatica (SAST) analisa a aplicacao em execucao, enquanto a analise dinamica (DAST) analisa apenas o codigo-fonte sem executa-lo.', 'Segurança Corporativa', 0, 'E o contrario: SAST (Static Application Security Testing) analisa o codigo-fonte sem executa-lo, enquanto DAST (Dynamic Application Security Testing) testa a aplicacao em execucao.', 1, 4),
('Um ataque de ''token replay'' pode ser mitigado usando tokens de uso unico (nonce) e validade de tempo curta (expiracao).', 'Autenticação Multifator', 1, 'Tokens com validade curta e uso unico impedem que um token capturado seja reutilizado com sucesso pelo atacante apos ser interceptado.', 1, 4),
('A tecnica de ''sandboxing'' executa um programa suspeito em um ambiente isolado para observar seu comportamento sem colocar em risco o sistema principal.', 'Malware', 1, 'O sandboxing e amplamente usado por solucoes de seguranca para analisar malware potencialmente perigoso sem impactar o ambiente de producao.', 1, 4),
('Sistemas de deteccao de intrusao baseados em assinatura (signature-based IDS) sao capazes de detectar qualquer ataque totalmente novo e desconhecido com a mesma eficacia de ataques conhecidos.', 'Incidentes de Segurança', 0, 'IDS baseados em assinatura dependem de padroes previamente conhecidos; ataques totalmente novos (zero-day) tendem a escapar dessa deteccao, sendo mais bem identificados por metodos baseados em comportamento/anomalia.', 1, 4),
('Um ''ataque de amplificacao NTP'' explora servidores de sincronizacao de tempo mal configurados para gerar trafego de negacao de servico em grande volume contra uma vitima.', 'Incidentes de Segurança', 1, 'Servidores NTP que respondem a comandos de monitoramento com respostas muito maiores que a requisicao podem ser abusados em ataques de amplificacao DDoS.', 1, 4),
('O uso de ''assinaturas de codigo'' (code signing) em softwares e drivers ajuda a verificar que o arquivo nao foi alterado apos ser publicado pelo desenvolvedor original.', 'Malware', 1, 'A assinatura digital do codigo permite verificar a integridade e a origem do software, dificultando a distribuicao de versoes adulteradas sem invalidar a assinatura.', 1, 4),
('Um programa de ''bug bounty'' remunera pesquisadores de seguranca externos que reportam vulnerabilidades encontradas de forma responsavel a organizacao.', 'Segurança Corporativa', 1, 'Esses programas incentivam a descoberta e o reporte etico de falhas antes que sejam exploradas maliciosamente, em troca de recompensas financeiras ou reconhecimento.', 1, 4),
('A tecnica de ''homomorphic encryption'' permite realizar calculos diretamente sobre dados criptografados sem a necessidade de descriptografa-los primeiro.', 'Boas Práticas de Segurança da Informação', 1, 'Essa forma avancada de criptografia permite processar dados sensiveis (por exemplo, em servicos de nuvem) sem expor o conteudo original em texto claro durante o processamento.', 1, 4),
('O conceito de ''attack surface reduction'' e alcancado unicamente pela instalacao de mais ferramentas de seguranca, independente da quantidade de servicos expostos.', 'Segurança Corporativa', 0, 'A reducao da superficie de ataque depende principalmente de eliminar servicos, portas e funcionalidades desnecessarias, e nao apenas de adicionar mais ferramentas de defesa.', 1, 4),
('Um ataque de ''JWT none algorithm'' explora implementacoes que aceitam tokens JSON Web Token assinados com o algoritmo declarado como ''none'', permitindo forjar tokens sem assinatura valida.', 'Autenticação', 1, 'Se a aplicacao nao validar corretamente o algoritmo declarado no cabecalho do token, um atacante pode enviar um token modificado com algoritmo ''none'' e ser aceito sem verificacao de assinatura.', 1, 4),
('A tecnica de ''memory forensics'' analisa o conteudo da memoria RAM de um sistema para identificar processos maliciosos que nao deixam vestigios no disco.', 'Incidentes de Segurança', 1, 'Malwares que operam apenas em memoria (fileless malware) podem nao deixar rastros no disco, tornando a analise forense de RAM essencial para sua deteccao.', 1, 4),
('Um ''ataque de confused deputy'' ocorre quando um componente com privilegios elevados e induzido a executar uma acao em nome de um atacante sem privilegios equivalentes.', 'Segurança Corporativa', 1, 'O componente privilegiado age como um ''procurador confuso'', usando sua propria autoridade para executar uma acao que o atacante nao poderia realizar diretamente.', 1, 4),
('A criptografia pos-quantica esta sendo desenvolvida porque computadores quanticos suficientemente poderosos poderiam quebrar com eficiencia alguns algoritmos assimetricos atuais, como RSA e ECC.', 'Boas Práticas de Segurança da Informação', 1, 'Algoritmos como o de Shor, executados em computadores quanticos, poderiam resolver problemas de fatoracao e logaritmo discreto de forma muito mais rapida, ameacando a seguranca do RSA e da ECC tradicionais.', 1, 4),
('Um ataque de ''IDOR'' (Insecure Direct Object Reference) ocorre quando uma aplicacao expoe referencias diretas a objetos internos (como IDs sequenciais) sem verificar corretamente a autorizacao do usuario.', 'Segurança Corporativa', 1, 'Sem a verificacao adequada, um usuario autenticado pode simplesmente alterar um ID na URL ou requisicao para acessar dados de outros usuarios.', 1, 4),
('Ferramentas de ''EDR'' (Endpoint Detection and Response) tem como unica funcao bloquear virus conhecidos, sem capacidade de monitorar comportamentos suspeitos em tempo real.', 'Segurança Corporativa', 0, 'Solucoes de EDR vao alem do antivirus tradicional, monitorando continuamente o comportamento dos endpoints para detectar e responder a atividades suspeitas, mesmo de ameacas desconhecidas.', 1, 4),
('O conceito de ''threat intelligence'' envolve coletar e analisar informacoes sobre ameacas, atacantes e suas taticas para apoiar decisoes de defesa mais informadas.', 'Incidentes de Segurança', 1, 'Threat intelligence transforma dados brutos sobre ameacas em conhecimento acionavel, ajudando equipes de seguranca a antecipar e priorizar defesas.', 1, 4);
