-- ============================================================
-- CYBER CHALLENGE - Dump inicial do banco (schema + dados)
-- ============================================================
-- Banco: MySQL 8.0+
--
-- Como usar (opcional -- a aplicacao tambem popula o banco sozinha
-- automaticamente na primeira execucao, caso as tabelas estejam vazias):
--
--   mysql -u root -p < sql/cyberchallenge_dump.sql
--
-- Isso cria o banco "cyberchallenge", as tabelas usadas pela aplicacao e
-- ja insere o estoque completo de 240 perguntas (60 por nivel),
-- deixando o banco pronto para uso imediato, sem depender do primeiro
-- start da aplicacao para popular os dados.
-- ============================================================

CREATE DATABASE IF NOT EXISTS cyberchallenge
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;

USE cyberchallenge;

-- ------------------------------------------------------------
-- Tabela: perguntas
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS perguntas (
    id                 BIGINT NOT NULL AUTO_INCREMENT,
    texto              TEXT NOT NULL,
    tema               VARCHAR(255) NOT NULL,
    resposta_correta   TINYINT(1) NOT NULL,
    explicacao         TEXT NOT NULL,
    ativa              TINYINT(1) NOT NULL DEFAULT 1,
    nivel              INT NOT NULL,
    PRIMARY KEY (id),
    KEY idx_perguntas_nivel_ativa (nivel, ativa)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- Tabela: participantes
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS participantes (
    id                  BIGINT NOT NULL AUTO_INCREMENT,
    nome                VARCHAR(255) NOT NULL,
    data_participacao   DATETIME NOT NULL,
    pontuacao           INT NULL,
    tempo_total         DOUBLE NULL,
    tempo_medio         DOUBLE NULL,
    idade               INT NULL,
    autoavaliacao       INT NULL,
    nivel               INT NULL,
    nota_final          DOUBLE NULL,
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- Tabela: respostas
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS respostas (
    id                BIGINT NOT NULL AUTO_INCREMENT,
    participante_id   BIGINT NOT NULL,
    pergunta_id       BIGINT NOT NULL,
    resposta          TINYINT(1) NOT NULL,
    correta           TINYINT(1) NOT NULL,
    tempo_resposta    DOUBLE NOT NULL,
    data_resposta     DATETIME NOT NULL,
    PRIMARY KEY (id),
    KEY idx_respostas_participante (participante_id),
    KEY idx_respostas_pergunta (pergunta_id),
    CONSTRAINT fk_respostas_participante FOREIGN KEY (participante_id) REFERENCES participantes (id),
    CONSTRAINT fk_respostas_pergunta FOREIGN KEY (pergunta_id) REFERENCES perguntas (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- Dados: estoque inicial de perguntas (240 linhas)
-- (mesmo conteudo de src/main/resources/seed/perguntas-seed.json)
-- ------------------------------------------------------------
